public static <T extends Comparable<T>> T max(List<T> items) {
    T max = items.get(0);
    for (T item : items) {
        if (item.compareTo(max) > 0) max = item;
    }
    return max;
}

// Producer extends: only reads numbers
double sum(List<? extends Number> numbers) {
    return numbers.stream().mapToDouble(Number::doubleValue).sum();
}

// Consumer super: only writes integers
void fill(List<? super Integer> target) {
    target.add(1);
    target.add(2);
}

// WRONG: raw type
List names = new ArrayList();
names.add(42);
String first = (String) names.get(0);   // ClassCastException at runtime

// RIGHT: the compiler rejects the wrong type
List<String> typed = new ArrayList<>();
typed.add(42);                          // compile error

// WRONG: changing an outside list from inside the stream
List<String> result = new ArrayList<>();
customers.stream().map(Customer::getName).forEach(result::add);

// RIGHT: the stream builds the result
List<String> result = customers.stream().map(Customer::getName).toList();

// WRONG: reusing a stream
Stream<Customer> s = customers.stream();
s.count();
s.count();   // IllegalStateException: stream has already been operated upon or closed

// Race condition
class Counter {
    private int value;
    void increment() { value++; }        // read, add, write: 3 steps
}

// Correct, without locks
class SafeCounter {
    private final AtomicInteger value = new AtomicInteger();
    void increment() { value.incrementAndGet(); }
}

// A ready-made concurrent structure
Map<String, Integer> visits = new ConcurrentHashMap<>();
visits.merge("/home", 1, Integer::sum);

// WRONG: two threads can both pass the check
if (!cache.containsKey(id)) {
    cache.put(id, load(id));
}

// RIGHT: atomic
cache.computeIfAbsent(id, this::load);

ExecutorService pool = Executors.newFixedThreadPool(10);

CompletableFuture<Customer> customer = CompletableFuture.supplyAsync(() -> customers.find(id), pool);
CompletableFuture<List<Order>> orders = CompletableFuture.supplyAsync(() -> ordersApi.list(id), pool);

Dashboard dashboard = customer
    .thenCombine(orders, Dashboard::new)
    .orTimeout(2, TimeUnit.SECONDS)
    .exceptionally(ex -> Dashboard.empty())
    .join();

// WRONG: blocking I/O on the common ForkJoinPool
CompletableFuture.supplyAsync(() -> httpClient.get(url));

// RIGHT: a dedicated executor for blocking work
CompletableFuture.supplyAsync(() -> httpClient.get(url), ioExecutor);

// Collect the result instead of changing outside state
List<Integer> doubled = numbers.stream().map(n -> n * 2).toList();

// Expressive grouping
Map<OrderStatus, Long> byStatus = orders.stream()
    .collect(Collectors.groupingBy(Order::status, Collectors.counting()));

// Side effects + parallel = unpredictable result
List<Integer> result = new ArrayList<>();
numbers.parallelStream().map(n -> n * 2).forEach(result::add);   // lost or duplicated items

